function geoLookup(ip: string): { country: string; flag: string; region: string } {
  const octets = ip.split(".");
  // Try progressively shorter prefixes for best match
  for (let len = 3; len >= 1; len--) {
    const prefix = octets.slice(0, len).join(".");
    const match = IP_GEO.find(r => r.prefix === prefix + (len < 4 ? "." : "") || r.prefix === prefix);
    if (match) return match;
  }
  return { country: "Unknown", flag: "🌐", region: "Unknown" };
}

