function CopyBtn({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
      className="ml-1 shrink-0 text-muted-foreground hover:text-primary" title="Copy IP">
      {copied ? <Check className="h-2.5 w-2.5 text-success" /> : <Copy className="h-2.5 w-2.5" />}
    </button>
  );
}

export default function GlobalMap() {
  const { toast } = useToast();
  const [items, setItems] = useState<ThreatItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [regionFilter, setRegionFilter] = useState("all");

  useEffect(() => {
    supabase
      .from("threat_items")
      .select("id,title,link,severity,source_name,iocs,published_at")
      .order("published_at", { ascending: false })
      .limit(500)
      .then(({ data, error }) => {
        if (error) toast({ title: "Load error", description: error.message, variant: "destructive" });
        else setItems((data || []).filter((i: any) => i.iocs?.ipv4?.length) as ThreatItem[]);
        setLoading(false);
      });
  }, [toast]);

  const byCountry = useMemo(() => {
    const map = new Map<string, { country: string; flag: string; region: string; ips: string[]; items: ThreatItem[]; severity: string }>();
    for (const item of items) {
      for (const ip of item.iocs?.ipv4 || []) {
        const geo = geoLookup(ip);
        const key = geo.country;
        const ex = map.get(key);
        if (ex) {
          if (!ex.ips.includes(ip)) ex.ips.push(ip);
          if (ex.items.length < 10 && !ex.items.find(i => i.id === item.id)) ex.items.push(item);
          if (item.severity === "critical") ex.severity = "critical";
          else if (item.severity === "high" && ex.severity !== "critical") ex.severity = "high";
        } else {
          map.set(key, { country: geo.country, flag: geo.flag, region: geo.region, ips: [ip], items: [item], severity: item.severity });
        }
      }
    }
    return [...map.values()].sort((a, b) => b.ips.length - a.ips.length);
  }, [items]);

  const totalIPs = useMemo(() => byCountry.reduce((a, c) => a + c.ips.length, 0), [byCountry]);
  const regions = [...new Set(byCountry.map(c => c.region))].sort();

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return byCountry.filter(c => {
      if (regionFilter !== "all" && c.region !== regionFilter) return false;
      if (q && !c.country.toLowerCase().includes(q) && !c.ips.some(ip => ip.includes(q))) return false;
      return true;
    });
  }, [byCountry, search, regionFilter]);

  const regionStats = useMemo(() => {
    const map = new Map<string, number>();
    for (const c of byCountry) map.set(c.region, (map.get(c.region) || 0) + c.ips.length);
    return [...map.entries()].sort((a, b) => b[1] - a[1]);
  }, [byCountry]);

  if (loading) return (
    <div className="container mx-auto px-4 py-8">
      <div className="text-center py-32 text-muted-foreground">Mapping threat origins…</div>
    </div>
  );

  return (
    <div className="container mx-auto px-4 py-8 max-w-screen-xl">
      <div className="mb-6">
        <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
          <Globe className="h-8 w-8 text-primary" />
          Global Threat Map
        </h1>
        <p className="text-muted-foreground mt-1">
          {totalIPs} threat IPs across {byCountry.length} countries/regions.
          Attribution based on IP prefix geolocation (~85% accuracy).
        </p>
      </div>

      {/* Region heatmap */}
      <div className="mb-6 grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-5">
        {regionStats.map(([region, count]) => (
          <button
            key={region}
            onClick={() => setRegionFilter(regionFilter === region ? "all" : region)}
            className={`rounded-lg border p-3 text-left transition-all hover:opacity-80 ${regionColors[region] || "border-border/40"} ${regionFilter === region ? "ring-1 ring-primary" : ""} bg-card/60`}
          >
            <div className="text-lg font-bold text-foreground">{count}</div>
            <div className="text-[10px] text-muted-foreground">{region}</div>
          </button>
        ))}
      </div>

      {/* Search */}
      <div className="mb-4 flex gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input placeholder="Search country or IP…" className="pl-9" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        {regionFilter !== "all" && (
          <Button variant="outline" size="sm" onClick={() => setRegionFilter("all")}>Clear filter</Button>
        )}
      </div>

      {filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">
          <Globe className="h-12 w-12 mx-auto mb-3 opacity-30" />
          <p>No IP indicators found yet. Feeds may still be loading.</p>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {filtered.map(entry => (
            <Card key={entry.country} className={`border ${regionColors[entry.region] || "border-border/60"} bg-card/60 backdrop-blur`}>
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base flex items-center gap-2">
                    <span className="text-2xl">{entry.flag}</span>
                    <div>
                      <div className="text-sm font-semibold">{entry.country}</div>
                      <div className="text-[10px] text-muted-foreground font-normal">{entry.region}</div>
                    </div>
                  </CardTitle>
                  <div className="flex flex-col items-end gap-1">
                    <Badge variant="outline" className="text-[10px]">{entry.ips.length} IP{entry.ips.length > 1 ? "s" : ""}</Badge>
                    {entry.severity === "critical" && (
                      <Badge className="text-[9px] bg-destructive/15 text-destructive border-destructive/40 border">CRIT</Badge>
                    )}
                  </div>
                </div>
                <div className="flex flex-wrap gap-1 mt-1">
                  {entry.ips.slice(0, 6).map(ip => (
                    <span key={ip} className="inline-flex items-center">
                      <a href={`https://www.abuseipdb.com/check/${ip}`} target="_blank" rel="noopener noreferrer">
                        <Badge variant="secondary" className="font-mono text-[9px] hover:border-primary/40">{ip}</Badge>
                      </a>
                      <CopyBtn value={ip} />
                    </span>
                  ))}
                  {entry.ips.length > 6 && (
                    <Badge variant="outline" className="text-[9px]">+{entry.ips.length - 6} more</Badge>
                  )}
                </div>
              </CardHeader>
              <CardContent className="pt-0">
                <div className="flex flex-col gap-1.5">
                  {entry.items.slice(0, 3).map(item => (
                    <div key={item.id} className="flex items-start gap-2">
                      <Badge className={`border text-[9px] shrink-0 mt-0.5 ${sevColor[item.severity] || ""}`}>
                        {item.severity.slice(0, 4).toUpperCase()}
                      </Badge>
                      <a href={item.link} target="_blank" rel="noopener noreferrer"
                        className="text-xs text-muted-foreground hover:text-primary truncate flex items-center gap-1">
                        <span className="truncate">{item.title}</span>
                        <ExternalLink className="h-2.5 w-2.5 shrink-0" />
                      </a>
                    </div>
                  ))}
                </div>
                <div className="mt-2 flex gap-2">
                  <a href={`https://viz.greynoise.io/riot?ip=${entry.ips[0]}`} target="_blank" rel="noopener noreferrer"
                    className="text-[10px] text-primary hover:underline">GreyNoise ↗</a>
                  <a href={`https://www.shodan.io/search?query=ip%3A${entry.ips[0]}`} target="_blank" rel="noopener noreferrer"
                    className="text-[10px] text-primary hover:underline">Shodan ↗</a>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <div className="mt-6 text-xs text-muted-foreground text-center">
        <AlertTriangle className="inline h-3 w-3 mr-1" />
        IP-to-country attribution uses prefix heuristics. For exact geolocation, use MaxMind GeoIP or ip-api.com.
        Tor exit nodes are identified as "Tor Network".
      </div>
    </div>
  );
}
